/**
 * Question Link: https://leetcode.com/problems/two-sum/
 */

class TwoSum {
    func twoSum(_ nums: [Int], _ target: Int) -> [Int] {
        var prevMap = [Int:Int]() // val -> index

        for (i, n) in nums.enumerated() {
            let diff = target - n
            if let firstIndex = prevMap[diff] {
                return [firstIndex, i]
            }
            prevMap[n] = i
        }
        return []
    }
}

/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     public var val: Int
 *     public var next: ListNode?
 *     public init() { self.val = 0; self.next = nil; }
 *     public init(_ val: Int) { self.val = val; self.next = nil; }
 *     public init(_ val: Int, _ next: ListNode?) { self.val = val; self.next = next; }
 * }
 */
class Solution {
    func addTwoNumbers(_ l1: ListNode?, _ l2: ListNode?) -> ListNode? {
        var itr1 = l1
        var itr2 = l2
        var carry: Int = 0
        var sum: Int = 0

        var dummy = ListNode(0)
        var head: ListNode? = dummy

        while itr1 != nil || itr2 != nil {
            let val1 = itr1?.val ?? 0
            let val2 = itr2?.val ?? 0

            sum = val1 + val2 + carry
            carry = sum/10
            sum = sum%10

            head?.next = ListNode(sum)
            head = head?.next

            itr1 = itr1?.next
            itr2 = itr2?.next
         }

        if carry > 0 {
            head?.next = ListNode(carry)
        }

        return dummy.next
    }
}

class Solution {
    func lengthOfLongestSubstring(_ s: String) -> Int {
        guard s.count > 0 else { return 0 }
        let list = Array(s)
        var hs = Set<Character>()
        var l = 0
        var r = 0
        var mv = 0
        for r in 0..<s.count {
            while hs.contains(list[r]) {
                hs.remove(list[l])
                l += 1
            }
            hs.insert(list[r])
            mv = max(mv, r - l + 1)
        }
        return mv
    }
}

class Solution {
    func findMedianSortedArrays(_ nums1: [Int], _ nums2: [Int]) -> Double {
        if nums1.count > nums2.count {
            return findMedianSortedArrays(nums2, nums1)
        }

        var m = nums1.count
        var n = nums2.count
        var l = 0
        var r = m

        while l <= r {
            var pa = (l + r) / 2
            var pb = (m + n + 1) / 2 - pa

            var maxLeftA = pa == 0 ? Int.min : nums1[pa - 1]
            var minRightA = pa == m ? Int.max : nums1[pa]
            var maxLeftB = pb == 0 ? Int.min : nums2[pb - 1]
            var minRightB = pb == n ? Int.max : nums2[pb]

            if maxLeftA <= minRightB && maxLeftB <= minRightA {
                if (m + n) % 2 == 0 {
                    return Double((max(maxLeftA, maxLeftB) + min(minRightA, minRightB))) / 2.0
                } else {
                    return Double(max(maxLeftA, maxLeftB))
                }
            } else if maxLeftA > minRightB {
                r = pa - 1
            } else {
                l = pa + 1
            }
        }

        return 0.0
    }
}

