 class Solution {
    func longestPalindrome(_ s: String) -> String {
        let s = Array(s)
        var res = ""
        var len = 0

        for i in 0..<s.count {
            var l = i
            var r = i
            while l >= 0 && r < s.count && s[l] == s[r] {
                if r - l + 1 > len {
                    res = String(s[l...r])
                    len = r - l + 1
                }
                l -= 1
                r += 1
            }

            l = i
            r = i + 1
            while l >= 0 && r < s.count && s[l] == s[r] {
                if r - l + 1 > len {
                    res = String(s[l...r])
                    len = r - l + 1
                }
                l -= 1
                r += 1
            }
        }

        return res
    }
}

class Solution {
    func reverse(_ x: Int) -> Int {
        let MIN = Int32.min
        let MAX = Int32.max

        var res = 0
        var value = x
        while value != 0 {
            let digit = value % 10
            value /= 10

            if res > MAX / 10 || (res == MAX / 10 && digit >= MAX % 10) {
                return 0
            }
            if res < MIN / 10 || (res == MIN / 10 && digit <= MIN % 10) {
                return 0
            }
            res = (res * 10) + digit
        }
        return res
    }
}

// Time: O(n)
// Space: O(1)
class Solution {
    func isPalindrome(_ x: Int) -> Bool {
        if x < 0 {
            return false
        }

        var div = 1
        while x >= 10 * div {
            div *= 10
        }

        var val = x
        while val > 0 {
            let right = val % 10
            let left = val / div

            if left != right {
                return false
            }

            val = (val % div) / 10
            div /= 100
        }
        return true
    }
}

class Solution {
    func isMatch(_ s: String, _ p: String) -> Bool {
        let s = Array(s), p = Array(p)
        var dp = [[Int]: Bool]()

        func dfs(_ i: Int, _ j: Int) -> Bool {
            if dp[[i, j]] != nil {
                return dp[[i, j]]!
            }
            if i >= s.count && j >= p.count {
                return true
            }
            if j >= p.count {
                return false
            }
            let isMatch = i < s.count && (s[i] == p[j] || p[j] == ".")
            if j + 1 < p.count && p[j + 1] == "*" {
                dp[[i, j]] = dfs(i, j + 2) || (isMatch && dfs(i + 1, j))
                return dp[[i, j]]!
            }
            if isMatch {
                dp[[i, j]] = dfs(i + 1, j + 1)
                return dp[[i, j]]!
            }
            dp[[i, j]] = false
            return false
        }

        return dfs(0, 0)
    }
}

class Solution {
    func maxArea(_ height: [Int]) -> Int {
        var maxArea = 0
        var l = 0
        var r = height.count - 1
        while l < r {
            let lV = height[l]
            let rV = height[r]
            let area = (r - l) * min(rV, lV)
            maxArea = max(area, maxArea)
            l += lV < rV  ? 1 : 0
            r -= lV >= rV ? 1 : 0
        }
        return maxArea
    }
}

class Solution {
    func longestCommonPrefix(_ strs: [String]) -> String {
        var newArray = strs.sorted()
        var string = ""

        for (char1, char2) in zip(newArray.first!, newArray.last!) {
            if (char1 == char2) {
                string.append(char1);
            } else {
                break
            }
        }
        return string
    }
}

class Solution {
    func threeSum(_ nums: [Int]) -> [[Int]] {
        let sortedArray = nums.sorted()
        var result: [[Int]] = []
        for i in 0..<sortedArray.count {
            if i > 0 && sortedArray[i] == sortedArray[i - 1] { continue }
            var l = i + 1
            var r = sortedArray.count - 1
            while l < r {
                var threeSum = sortedArray[i] + sortedArray[l] + sortedArray[r]
                if threeSum > 0 {
                    r -= 1
                } else if threeSum < 0 {
                    l += 1
                } else {
                    result.append([sortedArray[i], sortedArray[l], sortedArray[r]])
                    l += 1
                    while sortedArray[l] == sortedArray[l - 1] && l < r {
                        l += 1
                    }
                }
            }
        }
        return result
    }
}

class Solution {
    private let numberLetters: [Character: String] = [
        "2": "abc",
        "3": "def",
        "4": "ghi",
        "5": "jkl",
        "6": "mno",
        "7": "pqrs",
        "8": "tuv",
        "9": "wxyz"
    ]
    func letterCombinations(_ digits: String) -> [String] {
        guard !digits.isEmpty else { return [] }
        var result: [String] = []
        var digits = digits.map { $0 }
        func generateCombinations(_ index: Int, _ path: String) {
            guard index < digits.count else {
                result.append(path)
                return
            }
            let digit = digits[index]
            if let letters = numberLetters[digit] {
                for letter in letters {
                    generateCombinations(index + 1, path + "\(letter)")
                }
            }
        }
        generateCombinations(0, "")
        return result
    }
}

class Solution {
    func fourSum(_ nums: [Int], _ target: Int) -> [[Int]] {
        if nums.count < 4 {
            return []
        }

        var nums = nums.sorted()
        var res = [[Int]]()
        var quad = [Int]()

        func kSum(_ k: Int, _ start: Int, _ target: Int) {
            if k != 2 {
                for i in start..<nums.count - k + 1 {
                    if i > start && nums[i] == nums[i - 1] {
                        continue
                    }
                    quad.append(nums[i])
                    kSum(k - 1, i + 1, target - nums[i])
                    quad.popLast()
                }
                return
            } else {
                twoSum(start, target)
                return
            }
        }

        func twoSum(_ start: Int, _ target: Int) {
            var l = start
            var r = nums.count - 1
            while l < r {
                if nums[l] + nums[r] < target {
                    l += 1
                } else if nums[l] + nums[r] > target {
                    r -= 1
                } else {
                    res.append(quad + [nums[l], nums[r]])
                    repeat {
                        l += 1
                    } while l < r && nums[l] == nums[l - 1]
                }
            }
        }

        kSum(4, 0, target)

        return res
    }
}

/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     public var val: Int
 *     public var next: ListNode?
 *     public init() { self.val = 0; self.next = nil; }
 *     public init(_ val: Int) { self.val = val; self.next = nil; }
 *     public init(_ val: Int, _ next: ListNode?) { self.val = val; self.next = next; }
 * }
 */
class Solution {
    func removeNthFromEnd(_ head: ListNode?, _ n: Int) -> ListNode? {
        if head === nil {
            return head
        }
        var slow = head, fast = head
        for i in 1...n + 1 {
            if (slow === nil) {
                return head?.next
            }
            slow = slow?.next
        }

        while slow != nil {
            slow = slow?.next
            fast = fast?.next
        }
        fast?.next = fast?.next?.next
        return head
    }
}

class Solution {
    func isValid(_ s: String) -> Bool {
        let parenMap:[Character:Character] = ["(":")", "[":"]", "{":"}"]
        var stack = Stack<Character>()
        for c in s {
            if parenMap.keys.contains(c) {
                stack.push(c)
            } else if stack.isEmpty || c != parenMap[stack.pop()!] {
                return false
            }
        }
        return stack.isEmpty
    }
}

class Node<T> {
    var data: T
    var next: Node<T>?
    init(_ value: T) {
        self.data = value
    }
}

class Stack<T> {

    var head: Node<T>?

    var isEmpty: Bool {
        head == nil
    }

    func peak() -> Node<T>? {
        head
    }

    func push(_ data: T) {
        var node = Node<T>(data)
        node.next = head
        head = node
    }

    func pop() -> T? {
        var data = head?.data
        head = head?.next
        return data
    }
}

/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     public var val: Int
 *     public var next: ListNode?
 *     public init() { self.val = 0; self.next = nil; }
 *     public init(_ val: Int) { self.val = val; self.next = nil; }
 *     public init(_ val: Int, _ next: ListNode?) { self.val = val; self.next = next; }
 * }
 */
class Solution {
    func mergeTwoLists(
        _ list1: ListNode?,
        _ list2: ListNode?
    ) -> ListNode? {
        var dummyNode: ListNode? = ListNode(-10000)
        var resultNode = dummyNode

        var itr1 = list1
        var itr2 = list2

        while itr1 != nil && itr2 != nil {
            let v1 = itr1?.val ?? Int.max
            let v2 = itr2?.val ?? Int.max

            if v1 < v2 {
                resultNode?.next = itr1
                itr1 = itr1?.next
            } else {
                resultNode?.next = itr2
                itr2 = itr2?.next
            }

            resultNode = resultNode?.next
        }

        // itr1 is available only
        while itr1 != nil {
            resultNode?.next = itr1
            resultNode = resultNode?.next
            itr1 = itr1?.next
        }

        // itr2 is available only
        while itr2 != nil {
            resultNode?.next = itr2
            resultNode = resultNode?.next
            itr2 = itr2?.next
        }

        return dummyNode?.next
    }
}

// Time: O(2^n)
// Space: O(n)
class Solution {
    func generateParenthesis(_ n: Int) -> [String] {
        var result: [String] = []
        generate(n, 0, 0, "", &result)
        return result
    }

    func generate(_ n: Int, _ open: Int, _ close: Int, _ str: String, _ result: inout [String]) {
        if open == n && close == n {
            result.append(str)
            return
        }
        if open < n {
            generate(n, open + 1, close, str + "(", &result)
        }
        if open > close {
            generate(n, open, close + 1, str + ")", &result)
        }
    }
}

