/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     public var val: Int
 *     public var next: ListNode?
 *     public init() { self.val = 0; self.next = nil; }
 *     public init(_ val: Int) { self.val = val; self.next = nil; }
 *     public init(_ val: Int, _ next: ListNode?) { self.val = val; self.next = next; }
 * }
 */

class ReverseKGroup {
    func reverseKGroup(_ head: ListNode?, _ k: Int) -> ListNode? {
        var dummy = ListNode(0, head)
        var groupPrev: ListNode? = dummy

        while true {
            let kth = getKth(current: groupPrev, k: k)
            if kth == nil {
                break
            }

            let groupNext = kth?.next

            var prev = kth?.next
            var current = groupPrev?.next
            while current !== groupNext {
                let temp = current?.next
                current?.next = prev
                prev = current
                current = temp
            }

            let temp = groupPrev?.next
            groupPrev?.next = kth
            groupPrev = temp
        }

        return dummy.next
    }

    func getKth(current: ListNode?, k: Int) -> ListNode? {
        var current = current
        var k = k

        while current != nil && k > 0 {
            current = current?.next
            k -= 1
        }

        return current
    }
}

class Solution {
    func removeDuplicates(_ nums: inout [Int]) -> Int {
        var left: Int = 0

        for right in 1..<nums.count {
            if nums[right] != nums[left] {
                left += 1
                nums[left] = nums[right]
            }
        }

        return left + 1
    }
}

class Solution {
    func removeElement(_ nums: inout [Int], _ val: Int) -> Int {
        var count: Int = 0

        for i in nums where i != val {
            nums[count] = i
            count += 1
        }

        return count
    }
}

//Link: https://leetcode.com/problems/search-in-rotated-sorted-array/
class Solution {
    func search(_ nums: [Int], _ target: Int) -> Int {
        var lo = 0
        var hi = nums.count - 1

        while lo <= hi {
            let mid = lo + (hi-lo)/2
            if nums[mid] == target {
                return mid
            } else if nums[mid] <= nums[hi] {
                if target > nums[mid] && target <= nums[hi] {
                    lo = mid+1
                } else {
                    hi = mid-1
                }
            } else if nums[lo] <= nums[mid] {
                if target >= nums[lo] && target < nums[mid] {
                    hi = mid-1
                } else {
                    lo = mid+1
                }
            }
        }
        return -1
    }
}

class Solution {
    func searchRange(_ nums: [Int], _ target: Int) -> [Int] {
        let left = binSearch(nums, target, true)
        let right = binSearch(nums, target, false)
        return [left, right]
    }

    func binSearch(_ nums: [Int], _ target: Int, _ leftBias: Bool) -> Int {
        var left = 0, right = nums.count - 1
        var i = -1
        while left <= right {
            let mid = (left + right) / 2
            if target > nums[mid] {
                left = mid + 1
            }
            else if target < nums[mid] {
                right = mid - 1
            }
            else {
                i = mid
                if leftBias {
                    right = mid - 1
                }
                else {
                    left = mid + 1
                }
            }
        }
        return i
    }
}

class Solution {
    func isValidSudoku(_ board: [[Character]]) -> Bool {
        var rows: [Set<Character>] = []
        var cols: [Set<Character>] = []
        var subBoxes: [[Set<Character>]] = []
        for i in 1...9 {
            rows.append(Set<Character>())
            cols.append(Set<Character>())
        }
        for i in 1...3 {
            var row: [Set<Character>] = []
            for j in 1...3 {
                row.append(Set<Character>())
            }
            subBoxes.append(row)

        }
        for i in 0...8 {
            for j in 0...8 {
                let val: Character = board[i][j]
                if (val == ".") {
                    continue
                }
                if (rows[i].contains(val) || cols[j].contains(val) || subBoxes[i/3][j/3].contains(val)){
                    return false
                }
                rows[i].insert(val)
                cols[j].insert(val)
                subBoxes[i/3][j/3].insert(val)
            }
        }
        return true
    }
}

class Solution {
    func combinationSum(_ candidates: [Int], _ target: Int) -> [[Int]] {
        var result: [[Int]] = []
        var currentComb: [Int] = []
        func dfs(_ index: Int, _ remaining: Int) {
            guard index < candidates.count else { return }
            guard remaining >= 0 else {
                return
            }
            if remaining == 0 {
                result.append(currentComb)
                return
            }
            for i in index..<candidates.count {
                currentComb.append(candidates[i])
                dfs(i, remaining - candidates[i])
                currentComb.removeLast()
            }
        }
        dfs(0, target)
        return result
    }
}

class Solution {
    func combinationSum2(_ candidates: [Int], _ target: Int) -> [[Int]] {
        var candidates = candidates.sorted()
        var res = [[Int]]()
        var cur = [Int]()
        var total = 0

        func dfs(_ i: Int) {
            var i = i
            if total == target {
                res.append(cur)
                return
            }
            if total > target || i == candidates.count {
                return
            }

            cur.append(candidates[i])
            total += candidates[i]
            dfs(i + 1)
            cur.popLast()
            total -= candidates[i]
            while i + 1 < candidates.count && candidates[i] == candidates[i + 1] {
                i += 1
            }
            dfs(i + 1)
        }

        dfs(0)

        return res
    }
}

class Solution {
    func trap(_ height: [Int]) -> Int {
        if height == nil {
            return 0
        }

        var res = 0
        var l = 0
        var r = height.count - 1

        var leftMax = height[l]
        var rightMax = height[r]

        while l < r {
            if leftMax < rightMax {
                l += 1
                leftMax = max(leftMax, height[l])
                res += leftMax - height[l]
            } else {
                r -= 1
                rightMax = max(rightMax, height[r])
                res += rightMax - height[r]
            }
        }

        return res

    }

}

class Solution {
    func multiply(_ num1: String, _ num2: String) -> String {
        if [num1, num2].contains("0") {
            return "0"
        }

        var res = Array(repeating: 0, count: num1.count + num2.count)

        let n1 = Array(num1.reversed())
        let n2 = Array(num2.reversed())

        for i1 in 0..<n1.count {
            for i2 in 0..<n2.count {
                let digit = Int(String(n1[i1]))! * Int(String(n2[i2]))!
                res[i1 + i2] += digit
                res[i1 + i2 + 1] += res[i1 + i2] / 10
                res[i1 + i2] = res[i1 + i2] % 10
            }
        }

        res = res.reversed()
        var beg = 0

        while beg < res.count && res[beg] == 0 {
            beg += 1
        }

        return res[beg..<res.count].map { String($0) }.joined(separator: "")
    }
}

class Solution {
    func jump(_ nums: [Int]) -> Int {
        var left = 0, right = 0
        var res = 0

        while right < nums.count - 1 {
            var maxJump = 0
            for i in left...right {
                maxJump = max(maxJump, i + nums[i])
            }
            left = right + 1
            right = maxJump
            res += 1
        }
        return res
    }
}

class Solution {
    var ans: [[Int]] = []

    func permute(_ nums: [Int]) -> [[Int]] {
        var referenceNums = nums
        dfs(start: 0, currentOrder: &referenceNums)
        return ans
    }
}

private extension Solution {
    private func swap(_ arr: inout [Int], at i1: Int, with i2: Int) {
        guard
            i1 < arr.count,
            i2 < arr.count
        else { return }

        let temp = arr[i1]
        arr[i1] = arr[i2]
        arr[i2] = temp
    }

    func dfs(start: Int, currentOrder nums: inout [Int]) {
        // base case [take into final answer]
        if start == nums.count {
            ans.append(nums)
            return
        }

        // for each idx, take, switch with start, backtrack, switch back
        for i in start..<nums.count {
            // choose i.e. take it
            swap(&nums, at: i, with: start)

            // backtrack (from next idx)
            dfs(start: start + 1, currentOrder: &nums)

            // unchoose i.e. remove it
            swap(&nums, at: start, with: i)
        }
    }
}

/**
 * Question Link: https://leetcode.com/problems/permutations-ii/
 */

 class Solution {
    func permuteUnique(_ nums: [Int]) -> [[Int]] {
        var res = [[Int]]()
        var perm = [Int]()
        var count = [Int: Int]()
        for n in nums {
            count[n, default: 0] += 1
        }
        func dfs() {
            if perm.count == nums.count {
                res.append(perm)
                return
            }
            for n in count.keys {
                if count[n]! > 0 {
                    perm.append(n)
                    count[n, default: 0] -= 1
                    dfs()
                    count[n, default: 0] += 1
                    perm.popLast()
                }
            }
        }
        dfs()
        return res
    }
}

class Solution {
    func rotate(_ matrix: inout [[Int]]) {
        var left = 0, right = matrix.count - 1

        while left < right {
            for i in 0...right-left-1 {
                let top = left, bottom = right

                // save the topLeft
                let topLeft = matrix[top][left + i]

                // move bottom left into top left
                matrix[top][left + i] = matrix[bottom - i][left]

                // move bottom right into bottom left
                matrix[bottom - i][left] = matrix[bottom][right - i]

                // move top right into bottom right
                matrix[bottom][right - i] = matrix[top + i][right]

                // move top left into top right
                matrix[top + i][right] = topLeft
            }
            right -= 1
            left += 1
        }
    }
}

