 class Solution {
    func merge(_ intervals: [[Int]]) -> [[Int]] {
        var intervals = intervals.sorted { $0[0] < $1[0] }
        var res = [intervals[0]]

        for interval in intervals {
            let start = interval[0]
            let end = interval[1]
            let lastEnd = res[res.count - 1][1]

            if start <= lastEnd {
                res[res.count - 1][1] = max(lastEnd, end)
            } else {
                res.append([start, end])
            }
        }

        return res
    }
}

class Solution {
    func insert(_ intervals: [[Int]], _ newInterval: [Int]) -> [[Int]] {
        var res : [[Int]] = []
        var i = 0
        let n = intervals.count

        // parameters are immutable in Swift
        var currInterval = newInterval

        while i < n && intervals[i][1] < newInterval[0] {
            res.append(intervals[i])
            i += 1
        }

        while i < n && intervals[i][0] <= currInterval[1] {
            currInterval[0] = min(currInterval[0], intervals[i][0])
            currInterval[1] = max(currInterval[1], intervals[i][1])
            i += 1
        }
        res.append(currInterval)

        while i < n {
            res.append(intervals[i])
            i += 1
        }
        return res
    }
}

