class Solution {
    func minDistance(_ word1: String, _ word2: String) -> Int {
        // No operations needed if strings match
        if word1 == word2 {
            return 0
        }

        let m = word1.count, n = word2.count

        // if one word has no characters, min operations is length of other word
        if m == 0 {
            return n
        }
        if n == 0 {
            return m
        }

        var prev = 0
        var curr = Array(repeating: 0, count: n + 1)

        // convert the strings into an array
        let newWord1 = Array(word1)
        let newWord2 = Array(word2)

        for j in 1...n {
            curr[j] = j
        }

        for i in 1...m {
            var prev = curr[0]
            curr[0] = i
            for j in 1...n {
                let temp = curr[j]
                if newWord1[i - 1] == newWord2[j - 1] {
                    curr[j] = prev
                }
                else {
                    curr[j] = min(prev, min(curr[j - 1], curr[j])) + 1
                }
                prev = temp
            }
        }
        return curr[n]
    }
}

class Solution {
    func setZeroes(_ matrix: inout [[Int]]) {
        let rows = matrix.count, cols = matrix[0].count
        var rowZero = false

        for r in 0..<rows {
            for c in 0..<cols {
                if matrix[r][c] == 0 {
                    matrix[0][c] = 0
                    if r > 0 {
                        matrix[r][0] = 0
                    } else {
                        rowZero = true
                    }
                }
            }
        }

        for r in 1..<rows {
            for c in 1..<cols {
                if matrix[0][c] == 0 || matrix[r][0] == 0 {
                    matrix[r][c] = 0
                }
            }
        }

        if matrix[0][0] == 0 {
            for r in 0..<rows {
                matrix[r][0] = 0
            }
        }

        if rowZero {
            for c in 0..<cols {
                matrix[0][c] = 0
            }
        }
    }
}

class Solution {
    func searchMatrix(_ matrix: [[Int]], _ target: Int) -> Bool {
        let ROWS = matrix.count
        let COLS = matrix[0].count

        var row = ROWS - 1
        var col = 0

        while row >= 0 && col < COLS {
            let number = matrix[row][col]

            if number == target {
                return true
            }

            if number > target {
                row -= 1    // go up
            }
            else {
                col += 1    // go right
            }
        }

        return false
    }
}

