 class Solution {
    func combine(_ n: Int, _ k: Int) -> [[Int]] {
        var combs = [[Int]]()
        var curComb = [Int]()
        func dfs(_ i: Int) {
            if curComb.count == k {
                combs.append(curComb)
                return
            }
            if i > n {
                return
            }
            for j in i..<n + 1 {
                curComb.append(j)
                dfs(j + 1)
                curComb.popLast()
            }
        }
        dfs(1)
        return combs
    }
}

class Solution {
    func subsets(_ nums: [Int]) -> [[Int]] {
        var res : [[Int]] = []
        var subset : [Int] = []

        func dfs(_ i: Int) {
            if i >= nums.count {
                res.append(subset)
                return
            }
            // decision to include nums[i]
            subset.append(nums[i])
            dfs(i + 1)
            // decision NOT to include nums[i]
            subset.removeLast()
            dfs(i + 1)
        }

        dfs(0)
        return res
    }
}

class Solution {
    func removeDuplicates(_ nums: inout [Int]) -> Int {
        var l: Int = 0
        var r: Int = 0

        while r < nums.count {
            var count: Int = 1
            while r + 1 < nums.count && nums[r] == nums[r + 1] {
                r += 1
                count += 1
            }

            for _ in 0..<min(2, count) {
                nums[l] = nums[r]
                l += 1
            }

            r += 1
        }

        return l
    }
}

