class Solution {
    func isInterleave(_ s1: String, _ s2: String, _ s3: String) -> Bool {
        let s1 = Array(s1), s2 = Array(s2), s3 = Array(s3)
        if s3.count != s1.count + s2.count {
            return false
        }
        var dp = Array(repeating: false, count: s2.count + 1)
        for i in 0..<s1.count + 1 {
            for j in 0..<s2.count + 1 {
                if i == 0 && j == 0 {
                    dp[j] = true
                } else if i == 0 {
                    dp[j] = dp[j - 1] && s2[j - 1] == s3[i + j - 1]
                } else if j == 0 {
                    dp[j] = dp[j] && s1[i - 1] == s3[i + j - 1]
                } else {
                    dp[j] = (dp[j] && s1[i - 1] == s3[i + j - 1]) || (dp[j - 1] && s2[j - 1] == s3[i + j - 1])
                }
            }
        }
        return dp[s2.count]
    }
}

class Solution {
  func isValidBST(_ root: TreeNode?) -> Bool {
      return isBst(root, min: Int.min, max: Int.max)
  }

  private func isBst(_ node: TreeNode?, min: Int, max: Int) -> Bool {
    if node == nil { return true }
    if node!.val <= min || node!.val >= max { return false }
      let lc = isBst(node?.left, min: min, max: node!.val)
      let rc = isBst(node?.right, min: node!.val, max: max)
    return lc && rc
  }
}

class Solution {
    func isSameTree(_ p: TreeNode?, _ q: TreeNode?) -> Bool {
        if p == nil && q == nil { return true }
        if p?.val != q?.val { return false }
        return isSameTree(p?.left, q?.left) &&  isSameTree(p?.right, q?.right)
    }
}

class Solution {
    func levelOrder(_ root: TreeNode?) -> [[Int]] {
        guard let root = root else { return [] }
        var queue = [TreeNode]()
        var result = [[Int]]()
        queue.append(root)
        while !queue.isEmpty {
            var levelCount = queue.count
            var levelNodes = [Int]()
            while levelCount > 0 {
                let node = queue.first!
                queue.removeFirst()
                levelCount -= 1
                levelNodes.append(node.val)
                if let left = node.left {
                    queue.append(left)
                }

                if let right = node.right {
                    queue.append(right)
                }
            }
            result.append(levelNodes)
        }
        return result
    }

}

