/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     public var val: Int
 *     public var left: TreeNode?
 *     public var right: TreeNode?
 *     public init() { self.val = 0; self.left = nil; self.right = nil; }
 *     public init(_ val: Int) { self.val = val; self.left = nil; self.right = nil; }
 *     public init(_ val: Int, _ left: TreeNode?, _ right: TreeNode?) {
 *         self.val = val
 *         self.left = left
 *         self.right = right
 *     }
 * }
 */
class Solution {
    func buildTree(_ preorder: [Int], _ inorder: [Int]) -> TreeNode? {
        if preorder.isEmpty || inorder.isEmpty {
            return nil
        }

        var root = TreeNode(preorder[0])
        let mid = inorder.index(of: preorder[0])!
        root.left = buildTree(Array(preorder[1..<mid + 1]), Array(inorder[..<mid]))
        root.right = buildTree(Array(preorder[(mid + 1)...]), Array(inorder[(mid + 1)...]))

        return root
    }
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     public var val: Int
 *     public var left: TreeNode?
 *     public var right: TreeNode?
 *     public init() { self.val = 0; self.left = nil; self.right = nil; }
 *     public init(_ val: Int) { self.val = val; self.left = nil; self.right = nil; }
 *     public init(_ val: Int, _ left: TreeNode?, _ right: TreeNode?) {
 *         self.val = val
 *         self.left = left
 *         self.right = right
 *     }
 * }
 */
class Solution {
    func getMaxHeight(of root: TreeNode?) -> Int {
        guard let root = root else { return 0 }
        return 1 + max(
            getMaxHeight(of: root.left),
            getMaxHeight(of: root.right)
        )
    }

    func isBalanced(_ root: TreeNode?) -> Bool {
        guard let root = root else { return true }

        let leftHeight  = getMaxHeight(of: root.left)
        let rightHeight = getMaxHeight(of: root.right)
        let difference  = abs(leftHeight - rightHeight)

        // early exits
        guard difference <= 1 else { return false }
        guard isBalanced(root.left)  == true else { return false }
        guard isBalanced(root.right) == true else { return false }

        return true
    }
}

class Solution {
    func hasPathSum(_ root: TreeNode?, _ targetSum: Int) -> Bool {
        guard let root = root else { return false }

        if root.val == targetSum && !hasChild(root) { return true }

        return hasPathSum(root.left, targetSum - root.val) || hasPathSum(root.right, targetSum - root.val)
    }

    func hasChild(_ root: TreeNode) -> Bool {
        return (root.left != nil) || (root.right != nil)
    }
}

