class Solution {
    func ladderLength(_ beginWord: String, _ endWord: String, _ wordList: [String]) -> Int {
        var wordList = wordList
        if !wordList.contains(endWord) {
            return 0
        }

        var nei = [String: [String]]()
        wordList.append(beginWord)
        for word in wordList {
            for j in 0..<word.count {
                let pattern = word.prefix(j) + "*" + word.dropFirst(j + 1)
                nei[String(pattern), default: []].append(word)
            }
        }

        var visit = Set([beginWord])
        var q = [beginWord]
        var res = 1

        while !q.isEmpty {
            let count = q.count
            for _ in 0..<count {
                let word = q.removeFirst()
                if word == endWord {
                    return res
                }
                for j in 0..<word.count {
                    let pattern = word.prefix(j) + "*" + word.dropFirst(j + 1)
                    if let neiWords = nei[String(pattern)] {
                        for neiWord in neiWords {
                            if !visit.contains(neiWord) {
                                visit.insert(neiWord)
                                q.append(neiWord)
                            }
                        }
                    }
                }
            }
            res += 1
        }
        return 0
    }
}

class Solution {
    func longestConsecutive(_ nums: [Int]) -> Int {
        // remove duplicates numbers
        let numSet = Set(nums)
        var longestSequenceCount = 0
        // iterate through each number in the numSet
        // find the lowest number for a sequence, if num - 1 is not there in the numSet, it means num - 1 is the
        // lowest for that particular sequence
        for num in numSet where !numSet.contains(num - 1) {
            // num is lowest number for the probable longest consecutive sequence
            var visitingNum = num + 1
            var currentSequenceCount = 1
            // check if next number exists in the numSet, if so then increase the count
            while numSet.contains(visitingNum) {
                currentSequenceCount += 1
                visitingNum += 1
            }
            // set the maximum count
            longestSequenceCount = max(longestSequenceCount, currentSequenceCount)
        }
        return longestSequenceCount
    }
}

class Solution {
    func solve(_ board: inout [[Character]]) {
        var rows = board.count
        var columns = board[0].count

        // 1. DFS Capture unsurrounded regions (O -> T)
        for r in 0..<rows {
            for c in 0..<columns {
                if board[r][c] == "O" &&
                    ([0, rows - 1].contains(r) || [0, columns - 1].contains(c)) {
                    capture(r, c, &board)
                }
            }
        }

        // 2. Capture surrounded regions (O -> X)
        for r in 0..<rows {
            for c in 0..<columns {
                if board[r][c] == "O" {
                    board[r][c] = Character("X")
                }
            }
        }

        // 3. Uncapture surrounded regions (T -> O)
        for r in 0..<rows {
            for c in 0..<columns {
                if board[r][c] == "T" {
                    board[r][c] = Character("O")
                }
            }
        }
    }

    func capture(_ r: Int, _ c: Int, _ board: inout [[Character]]) {
        // Make sure r and c are in bounds
        guard r >= 0, r < board.count, c >= 0, c < board[0].count, board[r][c] == "O" else {
            return
        }

        board[r][c] = Character("T")

        capture(r - 1, c, &board)
        capture(r + 1, c, &board)
        capture(r, c - 1, &board)
        capture(r, c + 1, &board)
    }
}

class Solution {
    func isPalindrom(_ characters: [Character]) -> Bool {
        guard !characters.isEmpty else { return false }
        var i = 0
        var j = characters.count - 1
        while i < j {
            guard characters[i] == characters[j] else { return false }
            i += 1
            j -= 1
        }
        return true
    }
    func partition(_ s: String) -> [[String]] {
        var substrings: [String] = []
        var result: [[String]] = []
        let characters = s.map { $0 }

        func dfs(_ start: Int) {
            guard start < s.count else {
                result.append(substrings)
                return
            }
            for end in start..<characters.count {
                let substring = Array(characters[start...end])
                guard isPalindrom(substring) else { continue }
                substrings.append(substring.map { String($0) }.joined())
                dfs(end + 1)
                substrings.removeLast()
            }
        }
        dfs(0)
        return result
    }
}

