 *         self.neighbors = []
 *     }
 * }
 */

class Solution {
    var mapping: [Node?: Node?] = [:]

    func cloneGraph(_ node: Node?) -> Node? {
        guard let node = node else { return nil }
        // check if cache exists

        if mapping[node] != nil {
            return mapping[node]!
        }

        // otherwise, create a node, cache it, recurse for children
        let newNode = Node(node.val)
        mapping[node] = newNode

        node.neighbors.forEach { neighbor in
            newNode.neighbors.append(cloneGraph(neighbor))
        }
        return newNode
    }
}

class Solution {
    func canCompleteCircuit(_ gas: [Int], _ cost: [Int]) -> Int {
        if gas.reduce(0, +) < cost.reduce(0, +) {
            return -1
        }
        var start = gas.count - 1, end = 0
        var total = gas[start] - cost[start]

        while start >= end {
            while total < 0 && start >= end {
                start -= 1
                total += gas[start] - cost[start]
            }
            if start == end {
                return start
            }
            total += gas[end] - cost[end]
            end += 1
        }
        return -1
    }
}

