 */

class Solution {
    // Cache of mapping from old to new nodes
    private var mapping: [Node?: Node?] = [:]

    func copyRandomList(_ head: Node?) -> Node? {
        // Base case: Nil node
        guard let node = head else { return nil }

        // Mapping exists
        guard mapping[node] == nil else { return mapping[node]! }

        // Create new node
        let newNode = Node(node.val)

        // Add to cache (i.e. 'visit' this node)
        mapping[node] = newNode

        // Recursive calls (preorder -> children calls)
        newNode.next = copyRandomList(node.next)
        newNode.random = copyRandomList(node.random)

        return newNode
    }
}

class Solution {
    func wordBreak(_ s: String, _ wordDict: [String]) -> Bool {
        var s = Array(s)
        var dp = [Bool](repeating: false, count: s.count + 1)
        dp[s.count] = true

        for i in stride(from: s.count - 1, to: -1, by: -1) {
            for w in wordDict {
                if i + w.count <= s.count && String(s[i..<(i + w.count)]) == w {
                    dp[i] = dp[i + w.count]
                }
                if dp[i] {
                    break
                }
            }
        }

        return dp[0]
    }
}

