 * }
 */
class ReorderList {
    func reorderList(_ head: ListNode?) {
        var slow = head
        var fast = head?.next

        while fast != nil || fast?.next != nil {
            slow = slow?.next
            fast = fast?.next?.next
        }

        var second = slow?.next
        slow?.next = nil
        var prev: ListNode?

        while second != nil {
            var temp = second?.next
            second?.next = prev
            prev = second
            second = temp
        }

        var first = head
        second = prev

        while second != nil {
            var temp1 = first?.next
            var temp2 = second?.next
            first?.next = second
            second?.next = temp1
            first = temp1
            second = temp2
        }
    }
}

