class BSTIterator {
    var cur: TreeNode?
    var stack: [TreeNode]

    init(_ root: TreeNode?) {
        self.cur = root
        self.stack = []
    }

    func next() -> Int {
        while cur != nil || !stack.isEmpty {
            if cur != nil {
                stack.append(cur!)
                cur = cur?.left
            } else {
                cur = stack.popLast()
                let res = cur?.val ?? 0
                cur = cur?.right
                return res
            }
        }
        return -1
    }

    func hasNext() -> Bool {
        cur != nil || !stack.isEmpty
    }
}

