class Solution {
    func rightSideView(_ root: TreeNode?) -> [Int] {
        guard let root = root else { return [] }
        var result = [Int]()
        var queue: [TreeNode] = [root]

        while !queue.isEmpty {
            var temp = [Int]()
            for node in queue {
                let node = queue.removeFirst()
                if let leftNode = node.left, leftNode != nil { queue.append(leftNode) }
                if let rightNode = node.right, rightNode != nil { queue.append(rightNode) }
                temp.append(node.val)
            }
            result.append(temp.last!)
        }
        return result
    }
}

class Solution {

    func numIslands(_ grid: [[Character]]) -> Int {
        let ROWS = grid.count
        let COLS = grid[0].count

        var visited = [[Bool]](
            repeating: [Bool](repeating: false, count: COLS),
            count: ROWS
        )
        var count: Int = 0

        // Helper function to check if is within
        func isWithin(row: Int, col: Int) -> Bool {
            return (
                (row >= 0) && (col >= 0) &&
                (row < ROWS) && (col < COLS)
            )
        }

        // Helper function to check if cell is land or not
        func isLand(row: Int, col: Int) -> Bool {
            return grid[row][col] == "1"
        }

        let movementsX = [-1, 1, 0,  0]
        let movementsY = [0,  0, -1, 1]

        // Helper DFS function to 'visit' the grid
        func dfs(row: Int, col: Int) {
            // visit each child
            for (dirX, dirY) in zip(movementsX, movementsY) {
                let rowNew = row + dirX
                let colNew = col + dirY

                guard isWithin(row: rowNew, col: colNew) else { continue }
                guard visited[rowNew][colNew] == false else { continue }
                guard isLand(row: rowNew, col: colNew) else { continue }

                visited[rowNew][colNew] = true
                dfs(row: rowNew, col: colNew)
            }
        }

        for r in 0..<ROWS {
            for c in 0..<COLS {
                guard visited[r][c] == false  else { continue }
                guard isLand(row: r, col: c)  else { continue }

                visited[r][c] = true
                dfs(row: r, col: c)
                count += 1
            }
        }

        return count
    }
}

class Solution {
    func isHappy(_ n: Int) -> Bool {
        var slow = n, fast = sumSquareDigits(n)

        while slow != fast {
            fast = sumSquareDigits(fast)
            fast = sumSquareDigits(fast)
            slow = sumSquareDigits(slow)
        }

        return fast == 1
    }

    func sumSquareDigits(_ n: Int) -> Int {
        var output = 0
        var num = n
        while num != 0 {
            let currDigit = num % 10
            output += currDigit * currDigit
            num /= 10
        }
        return output
    }
}

class Solution {
    func isIsomorphic(_ s: String, _ t: String) -> Bool {
        guard s.count == t.count else { return false }

        var mapSourceToDest: [Character: Character] = [:]
        var mapDestToSource: [Character: Character] = [:]

        for (sourceChar, destChar) in zip(s, t) {
            if let sourceMapped = mapSourceToDest[sourceChar] {
                guard sourceMapped == destChar else { return false }
            } else {
                mapSourceToDest[sourceChar] = destChar
            }

            if let destMapped = mapDestToSource[destChar] {
                guard destMapped == sourceChar else { return false }
            } else {
                mapDestToSource[destChar] = sourceChar
            }
        }

        return true
    }
}

/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     public var val: Int
 *     public var next: ListNode?
 *     public init() { self.val = 0; self.next = nil; }
 *     public init(_ val: Int) { self.val = val; self.next = nil; }
 *     public init(_ val: Int, _ next: ListNode?) { self.val = val; self.next = next; }
 * }
 */
class Solution {
    func reverseList(_ head: ListNode?) -> ListNode? {
        if (head === nil || head?.next === nil) {
            return head
        }

        var prev: ListNode? = nil
        var curr = head, next = curr?.next

        while curr != nil {
            next = curr?.next
            curr?.next = prev
            prev = curr
            curr = next
        }
        return prev
    }
}

class Solution {
    func canFinish(_ numCourses: Int, _ prerequisites: [[Int]]) -> Bool {
        // map each course to prereq List
        var preMap = [Int: [Int]]()
        for num in 0..<numCourses {
            preMap[num] = []
        }

        for prerequisitePair in prerequisites {
            let course = prerequisitePair[0]
            let prerequisite = prerequisitePair[1]
            preMap[course, default: []] += [prerequisite]
        }

        // visitSet is all courses along the current DFS path
        var visitSet = Set<Int>()

        for crs in 0..<numCourses {
            let canCompleteCourse = dfs(crs, &preMap, &visitSet)
            if !canCompleteCourse {
                return false
            }
        }

        return true
    }

    func dfs(_ crs: Int, _ preMap: inout [Int: [Int]], _ visitSet: inout Set<Int>) -> Bool {
        guard !visitSet.contains(crs) else {
            return false
        }

        if preMap[crs] == [] {
            return true
        }

        visitSet.insert(crs)

        if let prerequisites = preMap[crs] {
            for pre in prerequisites {
                let canCompletePrerequisite = dfs(pre, &preMap, &visitSet)
                if !canCompletePrerequisite {
                    return false
                }
            }
        }

        visitSet.remove(crs)
        preMap[crs] = []

        return true
    }
}

