class Queue {
    var head: ListNode?
    var tail: ListNode?
    var size = 0

    func enqueue(_ val: Int) {
        let node = ListNode(val)
        if head == nil {
            head = node
            tail = node
        } else {
            tail?.next = node
            tail = tail?.next
        }
        size += 1
    }

    func dequeue() -> Int {
        if head == nil {
            return -1
        }
        let val = head?.val
        head = head?.next
        if head == nil {
            tail = nil
        }
        size -= 1
        return val ?? -1
    }
}

