        for _ in 0..<queue.size - 1 {
            let val = queue.dequeue()
            queue.enqueue(val)
        }
        return queue.dequeue()
    }

    func top() -> Int {
        queue.tail?.val ?? -1
    }

    func empty() -> Bool {
        queue.size == 0
    }
}

