class ValidAnagram {
    func isAnagram(_ s: String, _ t: String) -> Bool {
      if s.count != t.count {
        return false
      }
      var countS = [Int:Int]()
      var countT = [Int:Int]()
      let sChars = Array(s)
      let tChars = Array(t)
      for i in 0..<sChars.count {
          countS[Int(sChars[i].asciiValue!)] = 1 + countS[Int(sChars[i].asciiValue!), default: 0]
          countT[Int(tChars[i].asciiValue!)] = 1 + countT[Int(tChars[i].asciiValue!), default: 0]
      }
      for (key, _) in countS {
          if countS[key] != countT[key, default: 0] {
              return false
          }
      }
      return true
    }

    func isAnagramByLengthAndSortCheck(_ s: String, _ t: String) -> Bool {

        // if the String lengths don't match, then they cannot be anagrams of each other
        guard s.count == t.count else { return false }

        // sorting the String Characters puts them in the same order, which allows us to check equality
        guard s.sorted() == t.sorted() else { return false }

        // if both guards succeed, then we have an anagram
        return true
    }
}

class Solution {
    func canAttendMeetings(_ intervals: [[Int]]) -> Bool {
        if intervals.isEmpty {
            return true
        }

        var intervals = intervals.sorted(by: { $0[0] < $1[0] })
        var lastEnd = intervals[0][1]

        for i in 1..<intervals.count {
            let start = intervals[i][0]
            let end = intervals[i][1]

            if start >= lastEnd {
                lastEnd = intervals[i][1]
                continue
            } else {
                return false
            }
        }

        return true
    }
}

class Solution {
    func minMeetingRooms(_ intervals: [[Int]]) -> Int {
        var start = intervals.map({ $0[0] }).sorted()
        var end = intervals.map({ $0[1] }).sorted()
        var res = 0
        var count = 0
        var s = 0
        var e = 0

        while s < intervals.count {
            if start[s] < end[e] {
                s += 1
                count += 1
            } else {
                e += 1
                count -= 1
            }
            res = max(res, count)
        }

        return res
    }
}

class DisjointSet {
    private var ranks: [Int]
    private var roots: [Int]

    init(numVertices: Int) {
        ranks = [Int](repeating: 0, count: numVertices)
        roots = [Int](repeating: 0, count: numVertices)

        for i in 0..<numVertices {
            roots[i] = i
            ranks[i] = 1
        }
    }

    public func union(v1 x: Int, v2 y: Int) {
        let rootX = find(of: x)
        let rootY = find(of: y)

        guard rootX != rootY else { return }

        let rankX = ranks[rootX]
        let rankY = ranks[rootY]

        if rankX > rankY { // go into X
            roots[rootY] = rootX
        } else if rankY > rankX {   // go into Y
            roots[rootX] = rootY
        } else {    // go into X by default
            roots[rootY] = rootX
            ranks[rootX] += 1
        }
    }

    private func find(of x: Int) -> Int {
        if roots[x] == x { return x }
        roots[x] = find(of: roots[x])
        return roots[x]
    }

    public func areConnected(v1: Int, v2: Int) -> Bool {
        find(of: v1) == find(of: v2)
    }

    public func areDisjoint(v1: Int, v2: Int) -> Bool {
        !areConnected(v1: v1, v2: v2)
    }
}

class Solution {
    func validTree(_ n: Int, _ edges: [[Int]]) -> Bool {
        // Check if n-1 edges
        let numEdges = edges.count
        guard numEdges == (n - 1) else { return false }

        // Check if connected => Can use DisjointSet/UnionFind
        let ds = DisjointSet(numVertices: n)
        for edge in edges {
            let v1 = edge[0]; let v2 = edge[1]
            guard ds.areDisjoint(v1: v1, v2: v2) else {
                return false
            }
            ds.union(v1: v1, v2: v2)
        }

        return true;
    }
}

class Solution {
    func isUgly(_ n: Int) -> Bool {
        if n <= 0 {
            return false
        }

        var num = n
        for p in [2, 3, 5] {
            while num % p == 0 {
                num /= p
            }
        }
        return num == 1
    }
}

