 class Solution {
    func canPartition(_ nums: [Int]) -> Bool {
        let sum = nums.reduce(0, +)
        if sum % 2 != 0 {
            return false
        }

        var dp = Set<Int>()
        dp.insert(0)
        let target = sum / 2
        for i in stride(from: nums.count - 1, to: -1, by: -1) {
            var nextDP = Set<Int>()
            for t in dp {
                if t + nums[i] == target {
                    return true
                }
                nextDP.insert(t + nums[i])
                nextDP.insert(t)
            }
            dp = nextDP
        }
        return false
    }
}

class Solution {
    func pacificAtlantic(_ heights: [[Int]]) -> [[Int]] {
        let rows = heights.count
        let cols = heights[0].count
        var pac = Set<[Int]>()
        var atl = Set<[Int]>()
        var res = [[Int]]()

        func dfs(_ r: Int, _ c: Int, _ visit: inout Set<[Int]>, _ prevHeight: Int) {
            if r < 0 || c < 0 || r == rows || c == cols || visit.contains([r, c]) || heights[r][c] < prevHeight {
                return
            }
            visit.insert([r, c])
            dfs(r + 1, c, &visit, heights[r][c])
            dfs(r - 1, c, &visit, heights[r][c])
            dfs(r, c + 1, &visit, heights[r][c])
            dfs(r, c - 1, &visit, heights[r][c])
        }

        for c in 0..<cols {
            dfs(0, c, &pac, heights[0][c])
            dfs(rows - 1, c, &atl, heights[rows - 1][c])
        }

        for r in 0..<rows {
            dfs(r, 0, &pac, heights[r][0])
            dfs(r, cols - 1, &atl, heights[r][cols - 1])
        }

        for r in 0..<rows {
            for c in 0..<cols {
                if pac.contains([r, c]) && atl.contains([r, c]) {
                    res.append([r, c])
                }
            }
        }

        return res
    }
}

class Solution {
    func characterReplacement(_ s: String, _ k: Int) -> Int {
        var count: [Character: Int] = [:]
        var strArray = Array(s)
        var result = 0
        var l = 0
        var maxF = 0

        for r in 0...s.count - 1 {
            count[strArray[r]] = count[strArray[r], default: 0] + 1
            maxF = max(maxF, count[strArray[r], default: 0])

            while (r - l + 1) - maxF > k {
                count[strArray[l]] = count[strArray[l], default: 0] - 1
                l += 1
            }
            result = max(result, r - l + 1)
        }
        return result
    }
}

class Solution {
    func eraseOverlapIntervals(_ intervals: [[Int]]) -> Int {
        var intervals = intervals.sorted(by: { $0[0] < $1[0] })
        var res = 0
        var lastEnd = intervals[0][1]
        for i in 1..<intervals.count {
            let start = intervals[i][0]
            let end = intervals[i][1]
            if start >= lastEnd {
                lastEnd = end
            } else {
                res += 1
                lastEnd = min(lastEnd, end)
            }
        }
        return res
    }
}

