 */

 class PermutationInString {
    func checkInclusion(_ s1: String, _ s2: String) -> Bool {
        if s1.count > s2.count {
            return false
        }

        var s1Array = Array(s1)
        var s2Array = Array(s2)
        var arr1 = [Int](repeating: 0, count: 26)
        var arr2 = [Int](repeating: 0, count: 26)

        for i in 0..<s1Array.count {
            arr1[Int(s1Array[i].asciiValue! - Character("a").asciiValue!)] += 1
            arr2[Int(s2Array[i].asciiValue! - Character("a").asciiValue!)] += 1
        }

        var matches = 0
        for i in 0..<26 {
            if arr1[i] == arr2[i] {
                matches += 1
            }
        }

        var l = 0
        for r in s1Array.count..<s2Array.count {
            if matches == 26 {
                return true
            }

            var index = Int(s2Array[r].asciiValue! - Character("a").asciiValue!)
            arr2[index] += 1
            if arr1[index] == arr2[index] {
                matches += 1
            } else if arr1[index] + 1 == arr2[index] {
                matches -= 1
            }

            index = Int(s2Array[l].asciiValue! - Character("a").asciiValue!)
            arr2[index] -= 1
            if arr1[index] == arr2[index] {
                matches += 1
            } else if arr1[index] - 1 == arr2[index] {
                matches -= 1
            }

            l += 1
        }

        return matches == 26
    }
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     public var val: Int
 *     public var left: TreeNode?
 *     public var right: TreeNode?
 *     public init() { self.val = 0; self.left = nil; self.right = nil; }
 *     public init(_ val: Int) { self.val = val; self.left = nil; self.right = nil; }
 *     public init(_ val: Int, _ left: TreeNode?, _ right: TreeNode?) {
 *         self.val = val
 *         self.left = left
 *         self.right = right
 *     }
 * }
 */
class Solution {
    private func areSameTrees(
        _ node1: TreeNode?,
        _ node2: TreeNode?
    ) -> Bool {
        // if both are nil, they are same
        if node1 == nil && node2 == nil { return true }

        // if anyone else is nil, they are not the same
        guard let node1 = node1 else { return false }
        guard let node2 = node2 else { return false }

        return (
            (node1.val == node2.val) &&
            areSameTrees(node1.left, node2.left) &&
            areSameTrees(node1.right, node2.right)
        )
    }

    func isSubtree(_ root: TreeNode?, _ subRoot: TreeNode?) -> Bool {
        // Base cases (both can be nil, just any one can't)
        if root == nil && subRoot == nil { return true }
        guard let root = root else { return false }
        guard let subRoot = subRoot else { return false }

        // Base case: Exactly same tree
        if areSameTrees(root, subRoot) { return true }

        // Recursive
        return isSubtree(root.left, subRoot)
                || isSubtree(root.right, subRoot)
    }
}

