class Solution {
    func asteroidCollision(_ asteroids: [Int]) -> [Int] {
        var stack = [Int]()

        for var a in asteroids {
            while !stack.isEmpty && a < 0 && stack.last! > 0 {
                let diff = a + stack.last!
                if diff < 0 {
                    stack.popLast()
                } else if diff > 0 {
                    a = 0
                } else {
                    a = 0
                    stack.popLast()
                }
            }

            if a != 0 {
                stack.append(a)
            }
        }

        return stack
    }
}

class Solution {
    func dailyTemperatures(_ temperatures: [Int]) -> [Int] {
        let tempSize = temperatures.count
        var result = Array(repeating: 0, count: tempSize)

        for i in stride(from: tempSize - 1, through: 0, by: -1) {
            var j = i + 1

            while j < tempSize && temperatures[j] <= temperatures[i] {
                if result[j] <= 0 {
                    break
                }
                j += result[j]
            }

            if j < tempSize && temperatures[j] > temperatures[i] {
                result[i] = j - i
            }
        }

        return result
    }
}

