class Solution {
    func networkDelayTime(_ times: [[Int]], _ n: Int, _ k: Int) -> Int {
        var edges = [Int: [[Int]]]()
        for i in 1..<n + 1 {
            edges[i] = []
        }
        for t in times {
            let u = t[0]
            let v = t[1]
            let w = t[2]
            edges[u, default: []].append([v, w])
        }
        var visit = Set<Int>()
        var res = 0
        var minHeap = Heap()
        minHeap.push([0, k])
        while minHeap.count > 0 {
            let val = minHeap.pop()!
            let w1 = val[0]
            let n1 = val[1]
            if visit.contains(n1) {
                continue
            }
            visit.insert(n1)
            res = w1
            for e in edges[n1]! {
                let n2 = e[0]
                let w2 = e[1]
                if !visit.contains(n2) {
                    minHeap.push([w1 + w2, n2])
                }
            }
        }
        return visit.count == n ? res : -1
    }
}

