class Trie {
    let root = TrieNode()

    func insert(word: String, index: Int) {
        var cur = root
        for c in word {
            if cur.children[c] == nil {
                let node = TrieNode()
                node.index = index
                cur.children[c] = node
            }
            cur = cur.children[c]!
        }
        cur.isWord = true
    }

    func search(pref: String, suff: String) -> Int {
        var cur = root
        for c in suff + "#" + pref {
            if cur.children[c] == nil {
                return -1
            }
            cur = cur.children[c]!
        }
        return cur.index
    }
}

