class Solution {
    func swimInWater(_ grid: [[Int]]) -> Int {
        let n = grid.count
        var visit = Set<[Int]>()
        var minH = Heap()
        minH.push([grid[0][0], 0, 0])
        let directions = [[0, 1], [0, -1], [1, 0], [-1, 0]]
        visit.insert([0, 0])
        while minH.count > 0 {
            let val = minH.pop()!
            let t = val[0]
            let r = val[1]
            let c = val[2]
            if r == n - 1 && c == n - 1 {
                return t
            }
            for d in directions {
                let dr = d[0]
                let dc = d[1]
                var neiR = r + dr
                var neiC = c + dc
                if neiR < 0 || neiC < 0 || neiR == n || neiC == n || visit.contains([neiR, neiC]) {
                    continue
                }
                visit.insert([neiR, neiC])
                minH.push([max(t, grid[neiR][neiC]), neiR, neiC])
            }
        }
        return -1
    }
}

class Solution {
    func findCheapestPrice(_ n: Int, _ flights: [[Int]], _ src: Int, _ dst: Int, _ k: Int) -> Int {
        var prices = Array(repeating: Int.max, count: n)
        prices[src] = 0

        for i in 0..<(k + 1) {
            var tmp = prices

            for f in flights {
                let (s, d, p) = (f[0], f[1], f[2])
                if prices[s] == Int.max {
                    continue
                }
                if prices[s] + p < tmp[d] {
                    tmp[d] = prices[s] + p
                }
            }

            prices = tmp
        }

        return prices[dst] == Int.max ? -1 : prices[dst]
    }
}

