 class Solution {
    func numOfSubarrays(_ arr: [Int], _ k: Int, _ threshold: Int) -> Int {
        var res = 0
        var curSum = Array(arr[0..<k - 1]).reduce(.zero, +)
        for l in 0..<(arr.count - k + 1) {
            curSum += arr[l + k - 1]
            if curSum / k >= threshold {
                res += 1
            }
            curSum -= arr[l]
        }
        return res
    }
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     public var val: Int
 *     public var left: TreeNode?
 *     public var right: TreeNode?
 *     public init() { self.val = 0; self.left = nil; self.right = nil; }
 *     public init(_ val: Int) { self.val = val; self.left = nil; self.right = nil; }
 *     public init(_ val: Int, _ left: TreeNode?, _ right: TreeNode?) {
 *         self.val = val
 *         self.left = left
 *         self.right = right
 *     }
 * }
 */
class Solution {
    var globalCount: Int = 0

    func goodNodes(_ root: TreeNode?) -> Int {
        self.globalCount = 0
        visit(root, maxSoFar: nil)
        return self.globalCount
    }
}

private extension Solution {
    // DFS/Recursive traversal
    func visit(_ node: TreeNode?, maxSoFar: Int?) -> Void {
        // Base case 1. Node is nil
        guard let node = node else { return }

        // Base case 2. Initial value doesn't exist (in case of root)
        let maxVal: Int
        if let maxSoFar = maxSoFar  {
            maxVal = max(maxSoFar, node.val)
        } else {
            maxVal = node.val
        }

        // update global count
        if !(maxVal > node.val) {
            self.globalCount += 1
        }

        // visit children
        visit(node.left,  maxSoFar: maxVal)
        visit(node.right, maxSoFar: maxVal)
    }
}

